import type { Ingredient } from './ingredients';

/**
 * Standard home recipes for regional and global dishes. Each recipe lists the raw ingredients (grams) for ONE
 * serving and the cooked weight of that serving; nutrition is computed from the ingredient composition
 * (IFCT 2017 / USDA, see ingredients.ts) by scripts/build-foods.ts, the same recipe-calculation method used by
 * national food composition tables. Water is not listed (no nutrients) but is part of the cooked weight.
 * Every computed dish starts as "pending_review" until a nutrition reviewer approves it in the admin panel.
 */
export type Unit = 'piece' | 'plate' | 'bowl' | 'katori' | 'cup' | 'glass' | 'slice' | 'serving' | 'roll';
export interface Dish {
  id: string;
  name: string;
  aliases: string[];
  names?: Partial<Record<'te' | 'hi' | 'ta' | 'ar' | 'es' | 'pt' | 'fr' | 'de' | 'id', string>>;
  cuisine: string;
  category: string;
  countries: string[];
  unit: Unit;
  grams: number;
  recipe: Partial<Record<Ingredient, number>>;
}

type R = Dish['recipe'];
const IN = ['IN'];
const SI = 'South Indian';
const AT = 'Andhra and Telangana';
const NI = 'North Indian';
const ST = 'Indian street food';
const SW = 'Indian sweets';
const BV = 'Beverages';

function d(
  id: string,
  name: string,
  aliases: string[],
  cuisine: string,
  category: string,
  countries: string[],
  unit: Unit,
  grams: number,
  recipe: R,
  names?: Dish['names'],
): Dish {
  return { id, name, aliases, names, cuisine, category, countries, unit, grams, recipe };
}

// Reusable recipe bases (per serving).
const dosaBatter = (rice = 24, urad = 8): R => ({ rice, uradDal: urad, salt: 0.6 });
const idliBatter: R = { parboiledRice: 11, uradDal: 4, salt: 0.3 };
const tempering: R = { oil: 3, mustardSeeds: 0.5, curryLeaves: 0.5 };
const masalaAloo: R = { potato: 60, onion: 15, oil: 3, greenChilli: 1, turmeric: 0.2, salt: 0.6 };
const plus = (...parts: R[]): R => {
  const out: R = {};
  for (const p of parts) for (const [k, v] of Object.entries(p) as Array<[Ingredient, number]>) out[k] = (out[k] ?? 0) + v;
  return out;
};

